from collections import Counter
def transform(g):
    h,w=len(g),len(g[0]); k=3
    out=[[0]*(w//k) for _ in range(h//k)]
    freq=Counter(v for row in g for v in row)
    noise={c for c,_ in freq.most_common(2)}
    for bi in range(h//k):
        for bj in range(w//k):
            c=Counter()
            for i in range(bi*k,bi*k+k):
                for j in range(bj*k,bj*k+k):
                    c[g[i][j]]+=1
            cands=[(n,v) for v,n in c.items() if v not in noise and n>=2]
            if cands:
                n,v=max(cands)
                out[bi][bj]=v
    return out
