NOISE = {0, 5}


def block_grid(grid, k=3):
    """Split a grid into k x k blocks; returns list of row-lists of blocks."""
    return [
        [[grid[bi * k + i][bj * k + j] for j in range(k)] for i in range(k)]
        for bi in range(len(grid) // k)
        for bj in range(len(grid[0]) // k)
    ]


def mark_blocks(grid, noise=NOISE, threshold=1, k=3):
    """Per k x k block, return the most frequent non-noise color (with at least `threshold` cells) or 0."""
    out = []
    for bi in range(len(grid) // k):
        row = []
        for bj in range(len(grid[0]) // k):
            c = Counter(
                grid[bi * k + i][bj * k + j]
                for i in range(k)
                for j in range(k)
            )
            best, bn = 0, 0
            for v, n in c.items():
                if v not in noise and n >= threshold and n > bn:
                    best, bn = v, n
            row.append(best)
        out.append(row)
    return out
